options.onOkButtonClick:
this.getFormRef().validateForm(res=>{
  if(!res){
    return false;
  }

  const extraData = this.getExtraData();//获取外部带入数据对象（打开弹窗时通过打开弹窗事件带入的参数）
  const editFlag = extraData.editFlag;
  var apiName = '';
  let selDeviceType = this.getWidgetRef('deviceType',false);

  if(editFlag == 'add')
  {
    if(selDeviceType.getValue() == '1')
    {
      apiName = 'decoctionadd';
    }
    else if(selDeviceType.getValue() == '2')
    {
      apiName = 'packingadd';
    }
    else
    {
      apiName = 'dispensingadd';
    }
  }
  else
  {
    if(selDeviceType.getValue() == '1')
    {
      apiName = 'decoctionupdate';
    }
    else if(selDeviceType.getValue() == '2')
    {
      apiName = 'packingupdate';
    }
    else
    {
      apiName = 'dispensingupdate';
    }
  }

  this.getFormRef().submitFormData(apiName).then(res=>{
      this.$message.success("提交成功！")
      this.close();
    }).catch(error=>{
      this.$message.error("提交失败！")
      return false;
  })

})
return false;

